package cn.mop.api;
import cn.mop.domain.monitoring.ThresholdConditionAnalysis;
import cn.mop.domain.monitoring.ThresholdConditionAnalysis.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Synthetic candidate predicates only, no component input, customer confirmation or default threshold seed. */
class ThresholdConditionAnalysisTest {
    static BigDecimal n(String value){return value==null?null:new BigDecimal(value);}
    static Condition c(Comparison op,String value){return new Condition(op,n(value),"EXPLICIT_UNIT");}
    static Input high(){return new Input(Direction.HIGH_IS_BAD,c(Comparison.GT,"70"),c(Comparison.GT,"85"),c(Comparison.LT,"65"),n("300"),n("60"));}
    static Result result(Input input){return ThresholdConditionAnalysis.analyze(input);}
    static Set<Code> codes(Result result){Set<Code> codes=new HashSet<>();for(var issue:result.issues())codes.add(issue.code());return codes;}
    static Input conditions(Direction d,Condition w,Condition c,Condition r){return new Input(d,w,c,r,n("0"),n("0"));}
    @Test void explicitHighDirectionAndDisjointRecoveryAreMathematicallyConsistentOnly(){var r=result(high());assertEquals(Status.CONSISTENT,r.status());assertEquals(true,r.directionConsistent());assertEquals(true,r.criticalStrictSubsetOfWarning());assertEquals(false,r.recoveryOverlapsWarning());assertEquals(false,r.recoveryOverlapsCritical());assertEquals(true,r.durationsNonnegative());assertFalse(r.publishable());assertFalse(r.monitoringApplied());assertFalse(r.unitsConverted());assertNull(r.effectiveRule());assertEquals("NOT_RUN",r.physicalRangeCheck());assertEquals("UNVERIFIED",r.customerConfirmation());}
    @Test void lowIsBadKeepsProvidedOrderWithoutSwappingCandidateValues(){var input=conditions(Direction.LOW_IS_BAD,c(Comparison.LT,"60"),c(Comparison.LT,"30"),c(Comparison.GT,"65"));assertEquals(Status.CONSISTENT,result(input).status());assertEquals(n("60"),input.warning().threshold());assertEquals(n("30"),input.critical().threshold());}
    @Test void lowDirectionWithReversedCriticalOrderIsConflictNotAutoCorrection(){var input=conditions(Direction.LOW_IS_BAD,c(Comparison.LT,"95"),c(Comparison.LT,"99"),c(Comparison.GT,"99.5"));var r=result(input);assertEquals(Status.CONFLICT,r.status());assertEquals(false,r.criticalStrictSubsetOfWarning());assertTrue(codes(r).contains(Code.CRITICAL_NOT_STRICTER_THAN_WARNING));assertEquals(n("99"),input.critical().threshold());}
    @Test void sameDirectionRecoveryCannotBeReinterpretedAsOppositeOperator(){var input=conditions(Direction.HIGH_IS_BAD,c(Comparison.GT,"20"),c(Comparison.GT,"30"),c(Comparison.GT,"15"));var r=result(input);assertEquals(Status.CONFLICT,r.status());assertTrue(codes(r).containsAll(Set.of(Code.RECOVERY_DIRECTION_CONFLICT,Code.RECOVERY_OVERLAPS_WARNING,Code.RECOVERY_OVERLAPS_CRITICAL)));assertEquals(Comparison.GT,input.recovery().comparison());}
    @Test void strictAndInclusiveEqualBoundariesAreDistinguishedExactly(){for(Comparison warning:List.of(Comparison.GT,Comparison.GE))for(Comparison recovery:List.of(Comparison.LT,Comparison.LE)){var r=result(conditions(Direction.HIGH_IS_BAD,c(warning,"80"),c(Comparison.GT,"90"),c(recovery,"80")));boolean overlaps=warning==Comparison.GE&&recovery==Comparison.LE;assertEquals(overlaps,r.recoveryOverlapsWarning());assertEquals(overlaps?Status.CONFLICT:Status.CONSISTENT,r.status());}}
    @Test void sameNumericValueCanBeStrictSubsetOnlyByExplicitBoundaryOperator(){var yes=result(conditions(Direction.HIGH_IS_BAD,c(Comparison.GE,"80"),c(Comparison.GT,"80.0"),c(Comparison.LT,"70")));assertEquals(true,yes.criticalStrictSubsetOfWarning());var no=result(conditions(Direction.HIGH_IS_BAD,c(Comparison.GT,"80"),c(Comparison.GE,"80"),c(Comparison.LT,"70")));assertEquals(false,no.criticalStrictSubsetOfWarning());}
    @Test void identicalSeverityPredicatesAreNotDistinctLevelsEvenWithDifferentDecimalScale(){var r=result(conditions(Direction.HIGH_IS_BAD,c(Comparison.GT,"80"),c(Comparison.GT,"80.000"),c(Comparison.LT,"70")));assertEquals(false,r.criticalStrictSubsetOfWarning());assertTrue(codes(r).contains(Code.CRITICAL_NOT_STRICTER_THAN_WARNING));}
    @Test void decimalComparisonNeverUsesBinaryRounding(){var r=result(conditions(Direction.HIGH_IS_BAD,c(Comparison.GT,"0.99999999999999999"),c(Comparison.GT,"1"),c(Comparison.LT,"0.5")));assertEquals(Status.CONSISTENT,r.status());assertEquals(true,r.criticalStrictSubsetOfWarning());}
    @Test void negativeMetricThresholdsAllowedWithoutGuessingPhysicalRange(){assertEquals(Status.CONSISTENT,result(conditions(Direction.LOW_IS_BAD,c(Comparison.LT,"-5"),c(Comparison.LT,"-10"),c(Comparison.GT,"-1"))).status());}
    @Test void missingValuesRemainUnknownWithNoDefaultThresholdDurationOrDirection(){var r=result(null);assertEquals(Status.UNRESOLVED,r.status());assertNull(r.directionConsistent());assertNull(r.criticalStrictSubsetOfWarning());assertNull(r.recoveryOverlapsWarning());assertNull(r.durationsNonnegative());assertEquals(6,r.issues().size());assertFalse(r.publishable());}
    @Test void partialConditionPreservesUnknownRatherThanTreatingNullAsZero(){var r=result(conditions(Direction.HIGH_IS_BAD,new Condition(Comparison.GT,null,"EXPLICIT_UNIT"),c(Comparison.GT,"90"),c(Comparison.LT,"70")));assertEquals(Status.UNRESOLVED,r.status());assertNull(r.criticalStrictSubsetOfWarning());assertNull(r.recoveryOverlapsWarning());assertEquals(false,r.recoveryOverlapsCritical());}
    @Test void unitsMustMatchExactlyAndNoConversionIsInferred(){var input=high();var r=result(new Input(input.direction(),input.warning(),new Condition(Comparison.GT,n("85"),"OTHER_UNIT"),input.recovery(),input.triggerHoldSeconds(),input.recoveryHoldSeconds()));assertEquals(Status.CONFLICT,r.status());assertNull(r.criticalStrictSubsetOfWarning());assertNull(r.recoveryOverlapsCritical());assertTrue(codes(r).contains(Code.UNIT_MISMATCH));assertFalse(r.unitsConverted());}
    @Test void negativeDurationsConflictWhileExplicitZeroIsValidAndMissingIsUnknown(){var i=high();var r=result(new Input(i.direction(),i.warning(),i.critical(),i.recovery(),n("-0.1"),n("-1")));assertEquals(false,r.durationsNonnegative());assertTrue(codes(r).containsAll(Set.of(Code.NEGATIVE_TRIGGER_DURATION,Code.NEGATIVE_RECOVERY_DURATION)));var unknown=result(new Input(i.direction(),i.warning(),i.critical(),i.recovery(),null,n("0")));assertEquals(Status.UNRESOLVED,unknown.status());assertNull(unknown.durationsNonnegative());}
    @Test void recoveryCriticalOverlapDetectedEvenWhenWarningOrderAlreadyInvalid(){var r=result(conditions(Direction.HIGH_IS_BAD,c(Comparison.GT,"20"),c(Comparison.GT,"10"),c(Comparison.LT,"15")));assertEquals(false,r.recoveryOverlapsWarning());assertEquals(true,r.recoveryOverlapsCritical());assertTrue(codes(r).contains(Code.RECOVERY_OVERLAPS_CRITICAL));}
    @Test void malformedTechnicalFieldsAreRejectedWithoutEchoingRawData(){for(String unit:List.of(""," ","x\n","\ud800","x".repeat(33)))assertThrows(IllegalArgumentException.class,()->new Condition(Comparison.GT,n("1"),unit));for(String value:List.of("1e100","1e-100"))assertThrows(IllegalArgumentException.class,()->new Condition(Comparison.GT,n(value),"unit"));}
    Map<String,Object> wire(){Map<String,Object> v=new LinkedHashMap<>();v.put("direction","HIGH_IS_BAD");v.put("warning",Map.of("comparison","GT","threshold","70","unit","unit"));v.put("critical",Map.of("comparison","GT","threshold","85","unit","unit"));v.put("recovery",Map.of("comparison","LT","threshold","65","unit","unit"));v.put("trigger_hold_seconds","300");v.put("recovery_hold_seconds","60");return v;}
    @Test void strictWireCodecRejectsGuessedTypesExponentsAndUnknownFields(){assertEquals(Status.CONSISTENT,result(ThresholdConditionAnalysis.fromWire(wire())).status());for(Object value:List.of(1,1.0,"1e3","-0","-0.000","01","NaN","Infinity")){var v=wire();v.put("trigger_hold_seconds",value);assertThrows(IllegalArgumentException.class,()->ThresholdConditionAnalysis.fromWire(v));}var v=wire();v.put("publishable",true);assertThrows(IllegalArgumentException.class,()->ThresholdConditionAnalysis.fromWire(v));}
    @Test void wireNullsAreExplicitAndResultIssuesCannotBeMutated(){var v=wire();v.replaceAll((key,value)->null);var r=result(ThresholdConditionAnalysis.fromWire(v));assertEquals(Status.UNRESOLVED,r.status());assertThrows(UnsupportedOperationException.class,()->r.issues().clear());}
    @Test void knownConflictRemainsConflictEvenWhenOtherFieldsAreUnresolved(){var r=result(new Input(Direction.HIGH_IS_BAD,c(Comparison.LT,"70"),null,null,null,null));assertEquals(Status.CONFLICT,r.status());assertTrue(codes(r).contains(Code.WARNING_DIRECTION_CONFLICT));assertTrue(codes(r).contains(Code.CRITICAL_CONDITION_INCOMPLETE));assertNull(r.directionConsistent());}
    static boolean predicate(Comparison comparison,BigDecimal threshold,BigDecimal sample){int order=sample.compareTo(threshold);return switch(comparison){case GT->order>0;case GE->order>=0;case LT->order<0;case LE->order<=0;};}
    @Test void allComparatorFamiliesMatchIndependentPartitionSamplesIncludingBoundaryPoints(){
        List<BigDecimal> samples=List.of(n("-10"),n("-2"),n("-1"),n("0"),n("1"),n("2"),n("10"));
        for(Comparison w:Comparison.values())for(Comparison c:Comparison.values())for(Comparison r:Comparison.values())for(String wt:List.of("-2","0","2"))for(String ct:List.of("-2","0","2"))for(String rt:List.of("-2","0","2")){
            var result=result(conditions(Direction.HIGH_IS_BAD,c(w,wt),c(c,ct),c(r,rt)));boolean subset=true,proper=false,ow=false,oc=false;
            for(BigDecimal sample:samples){boolean wm=predicate(w,n(wt),sample),cm=predicate(c,n(ct),sample),rm=predicate(r,n(rt),sample);if(cm&&!wm)subset=false;if(wm&&!cm)proper=true;if(rm&&wm)ow=true;if(rm&&cm)oc=true;}
            assertEquals(subset&&proper,result.criticalStrictSubsetOfWarning());assertEquals(ow,result.recoveryOverlapsWarning());assertEquals(oc,result.recoveryOverlapsCritical());
        }
    }
    @Test void wireRejectsMissingFieldsWrongEnumAndForgedConditionMetadata(){
        for(String key:wire().keySet()){var v=wire();v.remove(key);assertThrows(IllegalArgumentException.class,()->ThresholdConditionAnalysis.fromWire(v));}
        var v=wire();v.put("direction","AUTO_DETECT");assertThrows(IllegalArgumentException.class,()->ThresholdConditionAnalysis.fromWire(v));
        for(Map<String,Object> condition:List.of(Map.<String,Object>of("comparison","greater","threshold","70","unit","unit"),Map.<String,Object>of("comparison","GT","threshold",70,"unit","unit"),Map.<String,Object>of("comparison","GT","threshold","70","unit","unit","published",true))){var candidate=wire();candidate.put("warning",condition);assertThrows(IllegalArgumentException.class,()->ThresholdConditionAnalysis.fromWire(candidate));}
    }
}
